import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"指标与可视化：容量、录制规则与面板发布","description":"容量、录制规则与面板发布：说明配置前提、操作对象、检查依据与失败处理。","frontmatter":{"title":"指标与可视化：容量、录制规则与面板发布","description":"容量、录制规则与面板发布：说明配置前提、操作对象、检查依据与失败处理。","showdocs":{"topics":[{"id":"metrics","title":"指标与可视化","link":"/topics/metrics/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"指标与可视化机制与任务课程","summary":"容量、录制规则与面板发布：说明配置前提、操作对象、检查依据与失败处理。","status":"active","related":[{"title":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"指标与面板：空图、统计口径与故障复盘","link":"/systems/logging-monitoring/metrics/diagnosis","kind":"排错与诊断","scope":"general","audience":"general"},{"title":"指标：序列、标签、Counter 与直方图","link":"/systems/logging-monitoring/metrics/metric-model","kind":"知识专题","scope":"general","audience":"general"},{"title":"Grafana 多数据源与面板配置","link":"/systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application"},"next":{"text":"指标与面板：空图、统计口径与故障复盘","link":"/systems/logging-monitoring/metrics/diagnosis"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application"},"next":{"text":"指标与面板：空图、统计口径与故障复盘","link":"/systems/logging-monitoring/metrics/diagnosis"}},"headers":[],"relativePath":"systems/logging-monitoring/metrics/plus/practice/operations.md","filePath":"systems/logging-monitoring/metrics/plus/practice/operations.md"}'),o={name:"systems/logging-monitoring/metrics/plus/practice/operations.md"};function s(n,e,l,c,p,g){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="指标与可视化-容量、录制规则与面板发布" tabindex="-1">指标与可视化：容量、录制规则与面板发布 <a class="header-anchor" href="#指标与可视化-容量、录制规则与面板发布" aria-label="Permalink to &quot;指标与可视化：容量、录制规则与面板发布&quot;">​</a></h1><p>维护Prometheus 指标与 Grafana 面板前先保存指标类型/单位、抓取窗口与数据源 UID，恢复后以原始序列、rate 聚合、空数据和面板单位验收。具体配置见<a href="/systems/logging-monitoring/metrics/plus/practice/application#source">配套示例</a>。</p><p>核对日期2026-10-17；适用范围：机制按核对时Prometheus 3.x官方文档的稳定共同子集说明；示例另固定Prometheus 2.55与Grafana OSS 11.6教学配置族，归档族不是生产安装建议。新版新增或实验功能未默认启用，实际升级仍需独立兼容与安全评估。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="/systems/logging-monitoring/metrics/base/basic/start#model">起点</a>理解前置，再按章节完成推演。</p><h2 id="capacity" tabindex="-1">采集容量与留存 <a class="header-anchor" href="#capacity" aria-label="Permalink to &quot;采集容量与留存 {#capacity}&quot;">​</a></h2><p>指标采集容量由活跃序列、抓取间隔、保留时间与查询并发共同决定。把15秒改为1秒增加采样量，却不保证发现一秒内所有事件；在抓取间隔间发生又消失的Gauge尖峰仍可能遗漏。先制定可接受延迟与资源预算，再设置间隔和保留策略。高基数失控时定位新增label维度，修正源头，不直接删除整个TSDB以掩盖问题。</p><h2 id="recording" tabindex="-1">录制规则和统计口径 <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;录制规则和统计口径 {#recording}&quot;">​</a></h2><p>指标录制规则将昂贵且稳定的表达式周期性保存为新序列，适合共享QPS或错误比率；它不自动回填规则启用前历史。命名应带业务含义和窗口，修改聚合维度前通知面板与告警消费者。分子与分母用同一过滤条件和窗口，整体错误率应先求错误总数与请求总数之比，不是平均各实例错误率，否则低流量实例被过度加权。</p><h2 id="publish" tabindex="-1">面板版本与权限 <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;面板版本与权限 {#publish}&quot;">​</a></h2><p>指标面板发布先在副本检查数据源UID、变量、单位和空数据，再记录JSON版本。provisioning提供可追溯文件来源，allowUiUpdates=false防止误以为UI保存会更新仓库文件；disableDeletion=true也意味着移除配置文件可能保留数据库面板。Viewer、Editor、Admin职责不同，面板可见性不能替代数据源后端授权。导出JSON前检查URL、账号标识与注释，不公开秘密。</p><h2 id="selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#selfcheck}&quot;">​</a></h2><p>练习：平均每实例错误率能代表全站错误率吗？</p><details><summary>参考解答</summary><p>不能。分母流量不同会引入权重错误，应先汇总相同窗口的失败请求与全部请求，再相除。</p></details><h2 id="references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#references}&quot;">​</a></h2><ul><li><p><a href="https://prometheus.io/docs/prometheus/latest/configuration/alerting_rules/" target="_blank" rel="noopener noreferrer">Prometheus 3.x当前规则文档核对</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/administration/provisioning/" target="_blank" rel="noopener noreferrer">Grafana provisioning核对</a></p></li><li><p><a href="https://prometheus.io/docs/prometheus/2.55/querying/functions/" target="_blank" rel="noopener noreferrer">PromQL函数2.55</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/datasources/prometheus/configure/" target="_blank" rel="noopener noreferrer">Grafana数据源</a></p></li><li><p><a href="https://github.com/prometheus/docs/blob/main/docs/tutorials/understanding_metric_types.md" target="_blank" rel="noopener noreferrer">指标类型官方教程</a></p></li></ul><p>继续阅读<a href="/systems/logging-monitoring/metrics/base/intermediate/mechanisms#types">机制</a>、<a href="/systems/logging-monitoring/metrics/plus/practice/application#files">完整实践</a>、<a href="/systems/logging-monitoring/metrics/plus/practice/operations#capacity">运维</a>、<a href="/systems/logging-monitoring/metrics/plus/troubleshooting/diagnostics#empty">诊断</a>与<a href="/systems/logging-monitoring/metrics/pro/review/review#exercise">复习</a>。</p><h2 id="legacy-containers-monitoring-compose-dependency-graph" tabindex="-1">监控编排的角色、挂载与采集范围 <a class="header-anchor" href="#legacy-containers-monitoring-compose-dependency-graph" aria-label="Permalink to &quot;监控编排的角色、挂载与采集范围 {#legacy-containers-monitoring-compose-dependency-graph}&quot;">​</a></h2><p>为什么监控 Compose 已列齐服务仍不能证明采集、告警和数据持久化完整？ 监控系统要分别画出采集、查询和告警链路：应用/Exporter 提供指标，Prometheus 抓取并保存，Grafana 查询，规则与 Alertmanager 再把告警路由到通知接收器。旧 Compose 虽同时列出 Prometheus、Alertmanager、Grafana、node-exporter、cAdvisor 和钉钉 Webhook，但 prometheus.yaml 只有文件名占位，告警规则、接收器配置与模板也未完整给出；容器清单不能证明链路闭合。依次核对 scrape target、规则文件路径、告警接收端和通知身份，不能把导入 dashboard 的数字 ID 当成采集配置。</p><p>采集范围必须从实际挂载和命名空间判断。node-exporter 在容器中暴露一个端口，并不自动证明采到了目标宿主的全部指标；cAdvisor 旧例把宿主根目录、/sys 与运行时目录挂入容器，其路径依赖真实 daemon 数据根且扩大读取范围。先声明要观察宿主、容器还是应用，再核对目标产品要求的挂载/权限；<a href="https://prometheus.io/docs/guides/node-exporter/" target="_blank" rel="noopener noreferrer">node-exporter 官方指南</a>解释了宿主指标角色。不能用另一台机器的 /data/docker_containers 路径填补该前置。</p><p>持久化与标签也各有责任：Grafana 的 /var/lib/grafana 保存面板等应用状态，不保存 Prometheus 时序数据；只挂 prometheus.yml 与 rules 不能证明 TSDB 被持久化。MySQL Exporter 需要数据库地址、受控采集身份和网络，旧 DATA_SOURCE_NAME 含 root 示例且未锁定版本，不能直接复用。跨 node/MySQL Exporter 的 instance 常含不同端口，面板联接前需明确共同主机标识，不能把数据库服务地址同时当作 Prometheus 数据源地址。恢复计划要覆盖采集配置、规则、面板与指标数据各自的位置，实际导入/查询和通知仍需另行验证。<a href="https://prometheus.io/docs/prometheus/latest/storage/" target="_blank" rel="noopener noreferrer">Prometheus 存储</a>是数据边界核对入口。</p>',19)])])}const h=a(o,[["render",s]]);export{d as __pageData,h as default};
